const projects=window.SILVER_VARIANTS,select=document.getElementById('project');
projects.forEach(p=>select.add(new Option(`${String(p.id).padStart(2,'0')} · ${p.name}`,p.id)));
let chosen=projects.findIndex(p=>p.id===Number(location.hash.slice(1)));if(chosen<0)chosen=12;
const frames=new Map();const original=document.getElementById('site');original.remove();
function show(){const p=projects[chosen];select.value=p.id;document.getElementById('count').textContent=`${chosen+1} / ${projects.length}`;document.getElementById('kind').textContent=p.type==='image'?'Archiwum makiet':'Kompletna wersja interaktywna';document.getElementById('standalone').href=p.file;history.replaceState(null,'',`#${p.id}`);frames.forEach(f=>f.hidden=true);const archive=document.getElementById('archive');archive.hidden=p.type!=='image';if(p.type==='image'){const img=document.getElementById('archive-image');img.src=p.file;img.alt=`Projekt ${p.id}: ${p.name}`;archive.scrollTop=0;}else{let frame=frames.get(p.id);if(!frame){frame=document.createElement('iframe');frame.title=`Projekt ${p.id}: ${p.name}`;frame.src=p.file;document.getElementById('stage').append(frame);frames.set(p.id,frame);}frame.hidden=false;}}
function move(delta){chosen=(chosen+delta+projects.length)%projects.length;show();}
document.getElementById('prev').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);select.onchange=()=>{chosen=projects.findIndex(p=>p.id===+select.value);show();};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight')move(1);});show();
window.addEventListener('message',e=>{if(![...frames.values()].some(frame=>frame.contentWindow===e.source))return;if(e.data?.type==='silver-project-step'&&[-1,1].includes(e.data.delta))move(e.data.delta);});
let touchStart=null;document.getElementById('archive').addEventListener('touchstart',e=>{touchStart=[e.changedTouches[0].clientX,e.changedTouches[0].clientY];},{passive:true});document.getElementById('archive').addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart[0],dy=e.changedTouches[0].clientY-touchStart[1];if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*2)move(dx<0?1:-1);touchStart=null;},{passive:true});
